c = int(input())
n = int(input())
tui = []
for _ in range(n):
    lenh = input().split()
    hanh_dong = lenh[0]
    ten = lenh[1]
    if hanh_dong == "ADD":
        if len(tui) < c:
            tui.append(ten)
    elif hanh_dong == "REMOVE":
        if ten in tui:
            tui.remove(ten)
for vat_pham in tui:
    print(vat_pham)
